using System.Diagnostics;
using System.Net.Sockets;
using Microsoft.Extensions.Logging;

// socket、logger、payload、connectionId、generation、requestId、ct
// 由目前連線 handler 提供。
long requestStart = Stopwatch.GetTimestamp();
DateTimeOffset startedUtc = DateTimeOffset.UtcNow;
logger.LogInformation(
    "send.started atUtc={AtUtc} connection={ConnectionId} generation={Generation} request={RequestId} bytes={Bytes}",
    startedUtc, connectionId, generation, requestId, payload.Length);

int sent = await socket.SendAsync(payload, SocketFlags.None, ct);
DateTimeOffset returnedUtc = DateTimeOffset.UtcNow;
double requestElapsedMs = Stopwatch.GetElapsedTime(requestStart).TotalMilliseconds;
logger.LogInformation(
    "send.returned atUtc={AtUtc} connection={ConnectionId} generation={Generation} request={RequestId} bytesReturned={BytesReturned} requestElapsedMs={RequestElapsedMs:F1}",
    returnedUtc, connectionId, generation, requestId, sent, requestElapsedMs);
